import json, datetime
try:
    raw = vars.get('products')
    if raw is None:
        raw = vars.get('get_account_node_response.data.products')
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            import ast
            raw = ast.literal_eval(raw)
    prods = raw if isinstance(raw, list) else []
    if not prods:
        i = 0
        while True:
            k = 'get_account_node_response.data.products.' + str(i) + '.product_id'
            if vars.get(k) is None: break
            p = {}
            for f in ['product_id','type','card_last4','past_due','days_late','minimum_payment','instalment_amount']:
                v = vars.get('get_account_node_response.data.products.' + str(i) + '.' + f)
                if v is not None: p[f] = v
            prods.append(p); i += 1
    out = []
    for idx, p in enumerate(prods):
        t = str(p.get('type'))
        dl = int(float(str(p.get('days_late') or 0)))
        if t == 'credit_card':
            name = 'credit card ending ' + str(p.get('card_last4') or '')
            floor = p.get('minimum_payment')
        elif t == 'car_loan':
            name = 'car loan'; floor = p.get('instalment_amount')
        else:
            name = 'personal loan'; floor = p.get('instalment_amount')
        if dl <= 7:
            band = 'early'; dead = vars.get('deadline_early'); att = 1
        else:
            band = 'late'; dead = vars.get('deadline_late'); att = 2
        out.append(str(idx+1) + '. product_id=' + str(p.get('product_id')) + ': ' + name + ', past due ' + str(p.get('past_due')) + ', ' + str(dl) + ' days late, band ' + band + ', DEADLINE ' + str(dead) + ', FLOOR ' + str(floor) + ', persuasion attempts allowed: ' + str(att) + (' (after the customer refuses attempt 1, make attempt 2 = floor on the deadline; if refused again: stop, product refused)' if att == 2 else ' (EARLY band: only ONE persuasion offer. After the first flat refusal of this product make attempt 1; if that is refused too, STOP: no second offer, product refused)'))
    vars['product_count'] = str(len(out))
    vars['product_facts'] = '\n'.join(out) if out else 'No product data returned.'
    vars['account_state'] = 'loaded' if out else 'empty'
except Exception as e:
    vars['product_facts'] = 'No product data.'
    vars['product_count'] = '0'
    vars['account_state'] = 'empty'

